'use client';

import { useTranslations } from 'next-intl';
import { personalInfo } from '@/data/career';
import { Mail, MapPin, Globe, Linkedin, Github } from 'iconoir-react';

interface ContactProps {
  locale: string;
}

export default function Contact({ locale }: ContactProps) {
  const t = useTranslations('contact');

  return (
    <section id="contact" className="py-20 bg-gray-50 dark:bg-gray-800">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-bold text-gray-900 dark:text-white mb-4">
            {t('title')}
          </h2>
          <p className="text-xl text-gray-600 dark:text-gray-400 mb-4">
            {t('subtitle')}
          </p>
          <p className="text-gray-600 dark:text-gray-400 max-w-2xl mx-auto">
            {t('description')}
          </p>
        </div>

        <div className="max-w-4xl mx-auto">
          <div className="bg-white dark:bg-gray-900 rounded-2xl p-8 md:p-12 shadow-lg">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div>
                <h3 className="text-2xl font-bold text-gray-900 dark:text-white mb-6">
                  Contact Information
                </h3>
                <div className="space-y-4">
                  <div className="flex items-center gap-3 text-gray-700 dark:text-gray-300">
                    <MapPin className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                    <div>
                      <p className="font-semibold">{t('location')}</p>
                      <p>{personalInfo.location}</p>
                    </div>
                  </div>

                  {personalInfo.email && (
                    <div className="flex items-center gap-3 text-gray-700 dark:text-gray-300">
                      <Mail className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                      <div>
                        <p className="font-semibold">{t('email')}</p>
                        <a
                          href={`mailto:${personalInfo.email}`}
                          className="hover:text-blue-600 dark:hover:text-blue-400 transition-colors"
                        >
                          {personalInfo.email}
                        </a>
                      </div>
                    </div>
                  )}

                  {personalInfo.website && (
                    <div className="flex items-center gap-3 text-gray-700 dark:text-gray-300">
                      <Globe className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                      <div>
                        <p className="font-semibold">{t('website')}</p>
                        <a
                          href={personalInfo.website}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="hover:text-blue-600 dark:hover:text-blue-400 transition-colors"
                        >
                          {personalInfo.website}
                        </a>
                      </div>
                    </div>
                  )}
                </div>
              </div>

              <div>
                <h3 className="text-2xl font-bold text-gray-900 dark:text-white mb-6">
                  Social Links
                </h3>
                <div className="space-y-4">
                  {personalInfo.linkedin && (
                    <a
                      href={personalInfo.linkedin}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-3 text-gray-700 dark:text-gray-300 hover:text-blue-600 dark:hover:text-blue-400 transition-colors"
                    >
                      <Linkedin className="w-5 h-5" />
                      <span className="font-semibold">{t('linkedin')}</span>
                    </a>
                  )}

                  {personalInfo.github && (
                    <a
                      href={personalInfo.github}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-3 text-gray-700 dark:text-gray-300 hover:text-blue-600 dark:hover:text-blue-400 transition-colors"
                    >
                      <Github className="w-5 h-5" />
                      <span className="font-semibold">{t('github')}</span>
                    </a>
                  )}

                  {personalInfo.upwork && (
                    <a
                      href={personalInfo.upwork}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-3 text-gray-700 dark:text-gray-300 hover:text-blue-600 dark:hover:text-blue-400 transition-colors"
                    >
                      <Globe className="w-5 h-5" />
                      <span className="font-semibold">{t('upwork')}</span>
                    </a>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

